int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int ret = 0;
    unsigned char *src = from;
    unsigned char *dst = to;
    unsigned char *end = to + tolen;

    while (src < from + fromlen && dst < end - 1) {
        unsigned char type = *src++;
        if (type == 0) {
            // Current directory
            *dst++ = '.';
        } else if (type == 1) {
            // Parent directory
            if (dst == to) {
                *dst++ = '.';
            } else if (dst > to + 1 && *(dst - 1) == '.') {
                *dst++ = '.';
            } else {
                *dst++ = '.';
                *dst++ = '.';
            }
        } else if (type == 2) {
            // Symlink
            if (dst > to && dst < end) {
                *(dst - 1) = '/';
            } else {
                ret = -ENOSPC;
                break;
            }
        } else {
            // Named component
            int len = *src++;
            if (dst + len >= end) {
                ret = -ENOSPC;
                break;
            }
            memcpy(dst, src, len);
            dst += len;
            src += len;
            if (dst < end) {
                *dst++ = '/';
            }
        }
    }

    if (dst < end) {
        *dst = '\0';
    } else {
        ret = -ENOSPC;
    }

    return ret;
}

int path_to_user(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i;
    unsigned char *dst = to;

    while (fromlen--) {
        if (dst >= to + tolen) {
            return -ENAMETOOLONG;
        }

        if (*from == '/') {
            *dst++ = *from;
        } else if (*from == '.') {
            if (fromlen && from[1] == '.') {
                if (dst > to) {
                    if (dst[-1] != '/') {
                        if (dst >= to + tolen) {
                            return -ENAMETOOLONG;
                        }
                        *dst++ = '/';
                    }
                }
                *dst++ = *from++;
                fromlen--;
            } else {
                *dst++ = *from;
            }
        } else {
            *dst++ = *from;
        }
        from++;
    }

    if (dst >= to + tolen) {
        return -ENAMETOOLONG;
    }

    *dst = '\0';
    return 0;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int offset = 0;

    while (offset < fromlen) {
        int component_type = from[offset];

        if (component_type == 0) {
            if (tolen <= 0 || tolen-- <= 0) {
                return -1; // Buffer overflow error
            }
            *to++ = '\0';
            offset++;
        } else if (component_type == 1) {
            if (tolen <= 0 || tolen-- <= 0) {
                return -1; // Buffer overflow error
            }
            *to++ = '.';
            offset++;
        } else if (component_type == 2) {
            if (tolen <= 0 || tolen-- <= 0) {
                return -1; // Buffer overflow error
            }
            *to++ = '.';
            offset++;
        } else if (component_type == 3) {
            int symlink_len = from[offset + 1];
            if (offset + 1 + symlink_len > fromlen) {
                return -1; // Invalid symlink data
            }
            for (int i = 0; i < symlink_len; i++) {
                if (tolen <= 0 || tolen-- <= 0) {
                    return -1; // Buffer overflow error
                }
                *to++ = from[offset + 2 + i];
            }
            offset += 2 + symlink_len;
        } else {
            int name_len = from[offset + 1];
            if (offset + 1 + name_len > fromlen) {
                return -1; // Invalid name data
            }
            for (int i = 0; i < name_len; i++) {
                if (tolen <= 0 || tolen-- <= 0) {
                    return -1; // Buffer overflow error
                }
                *to++ = from[offset + 2 + i];
            }
            offset += 2 + name_len;
        }
    }

    if (tolen <= 0 || tolen-- <= 0) {
        return -1; // Buffer overflow error
    }
    *to++ = '\0';

    return 0;
}

int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;
    int len = 0;

    if (!from || !to) {
        return -EINVAL;
    }

    while (i < fromlen) {
        unsigned char type = from[i];
        unsigned char lenbytes = from[i + 1];
        int component_len = 0;

        if (j + 1 >= tolen) {
            return -ENAMETOOLONG;
        }

        switch (type) {
            case 0x00:
                if (j > 0 && to[j - 1] != '/') {
                    if (j + 1 >= tolen) {
                        return -ENAMETOOLONG;
                    }
                    to[j++] = '/';
                }
                break;
            case 0x01:
                if (j > 0 && to[j - 1] != '/') {
                    if (j + 1 >= tolen) {
                        return -ENAMETOOLONG;
                    }
                    to[j++] = '/';
                }
                if (j + 1 >= tolen) {
                    return -ENAMETOOLONG;
                }
                to[j++] = '.';
                break;
            case 0x02:
                if (j > 0 && to[j - 1] != '/') {
                    if (j + 1 >= tolen) {
                        return -ENAMETOOLONG;
                    }
                    to[j++] = '/';
                }
                if (j + 2 >= tolen) {
                    return -ENAMETOOLONG;
                }
                to[j++] = '.';
                to[j++] = '.';
                break;
            default:
                if (lenbytes < 1 || lenbytes > 4) {
                    return -EINVAL;
                }
                component_len = 0;
                for (int k = 0; k < lenbytes; k++) {
                    component_len |= from[i + 2 + k] << (8 * k);
                }

                if (j + component_len > tolen) {
                    return -ENAMETOOLONG;
                }

                for (int k = 0; k < component_len; k++) {
                    to[j++] = from[i + 2 + lenbytes + k];
                }

                break;
        }

        i += 2 + lenbytes + component_len;
    }

    if (j >= tolen) {
        return -ENAMETOOLONG;
    }

    to[j] = '\0';
    return 0;
}

int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int offset = 0;
    int i = 0;

    while (i < fromlen) {
        unsigned char type = from[i];

        if (offset + 1 >= tolen)
            return -ENAMETOOLONG;

        switch (type) {
            case SYMLINK_TYPE:
                if (offset + 1 >= tolen)
                    return -ENAMETOOLONG;
                to[offset++] = 'l';
                break;
            case PARENT_DIR_TYPE:
                if (offset + 2 >= tolen)
                    return -ENAMETOOLONG;
                to[offset++] = '.';
                to[offset++] = '.';
                break;
            case CURRENT_DIR_TYPE:
                if (offset + 1 >= tolen)
                    return -ENAMETOOLONG;
                to[offset++] = '.';
                break;
            default:
                // Treat unknown type as an error
                return -EINVAL;
        }

        i += 1;
    }

    if (offset >= tolen)
        return -ENAMETOOLONG;

    to[offset] = '\0';
    return 0;
}
